/**
 * Amount structure with currency
 */
export interface CouponAmount {
    amount: string;
    currency: string;
}
/**
 * Coupon data structure interface (matches API response)
 */
export interface Coupon {
    /** Unique coupon code */
    code: string;
    /** Discount amount (number, string, or CouponAmount object for fixed coupons) */
    amount: number | string | CouponAmount;
    /** Type of discount - percentage or fixed */
    type: 'percentage' | 'fixed';
    /** Minimum cart amount required to use this coupon */
    minimum_amount?: CouponAmount;
    /** Maximum discount amount (for percentage coupons) */
    maximum_amount?: CouponAmount;
    /** Remaining days until expiry */
    remaining_days?: number;
    /** Whether this coupon includes free shipping */
    free_shipping?: number | boolean;
}
/**
 * One entry in the unified coupon list (CP-3695).
 *
 * The cart page used to render applied coupons as bare text chips AND checkout coupons as
 * cards, so a coupon that was both showed up twice. This type is the join of the two: one
 * row per code, carrying whether it is currently applied.
 *
 * `coupon` is null when the code is applied but has no card metadata — the cart payload
 * sends applied coupons as plain strings (`CartResource`: `'coupons' => getCouponCodes()`),
 * so a manually typed code, or one with `show_checkout_coupon = 0`, has no amount, expiry
 * or minimum to render. Those show as a minimal code-only card.
 */
export interface MergedCoupon {
    /** The coupon code — the join key between the applied set and the checkout-coupon list. */
    code: string;
    /** Card metadata from the checkout-coupons endpoint, or null for a metadata-less code. */
    coupon: Coupon | null;
    /** Whether this coupon is currently applied to the cart. */
    applied: boolean;
}
